import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

bn_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor batchnorm2d_forward(torch::Tensor x,
                                   torch::Tensor weight,
                                   torch::Tensor bias,
                                   torch::Tensor running_mean,
                                   torch::Tensor running_var,
                                   bool training,
                                   double momentum,
                                   double eps);
"""

bn_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void batchnorm2d_kernel(
    const T* __restrict__ X,
    T* __restrict__ Y,
    const T* __restrict__ weight,
    const T* __restrict__ bias,
    T* __restrict__ running_mean,
    T* __restrict__ running_var,
    int N, int C, int H, int W,
    float eps, float momentum, bool training)
{
  const int c   = blockIdx.x;
  const int tid = threadIdx.x;
  const int nthreads = blockDim.x;

  const int64_t HW    = (int64_t)H * W;
  const int64_t count = (int64_t)N * HW;
  const int64_t Cstride = (int64_t)C * HW;

  // View this channel's data as an (N, H, W) tensor using CuTe.
  auto mX = make_tensor(make_gmem_ptr(X + (int64_t)c * HW),
                         make_shape(N, H, W),
                         make_stride(Cstride, (int64_t)W, Int<1>{}));
  auto mY = make_tensor(make_gmem_ptr(Y + (int64_t)c * HW),
                         make_shape(N, H, W),
                         make_stride(Cstride, (int64_t)W, Int<1>{}));

  float mean, inv_std;

  extern __shared__ float smem[];
  float* s_sum   = smem;
  float* s_sumsq = smem + nthreads;

  if (training) {
    float sum = 0.0f, sumsq = 0.0f;
    for (int64_t idx = tid; idx < count; idx += nthreads) {
      int n   = (int)(idx / HW);
      int rem = (int)(idx % HW);
      int h   = rem / W;
      int w   = rem % W;
      float v = (float)mX(n, h, w);
      sum   += v;
      sumsq += v * v;
    }

    s_sum[tid]   = sum;
    s_sumsq[tid] = sumsq;
    __syncthreads();

    for (int stride = nthreads / 2; stride > 0; stride >>= 1) {
      if (tid < stride) {
        s_sum[tid]   += s_sum[tid + stride];
        s_sumsq[tid] += s_sumsq[tid + stride];
      }
      __syncthreads();
    }

    __shared__ float s_mean, s_inv_std;
    if (tid == 0) {
      float m = s_sum[0] / (float)count;
      float v = s_sumsq[0] / (float)count - m * m;
      if (v < 0.0f) v = 0.0f;
      s_mean    = m;
      s_inv_std = rsqrtf(v + eps);

      if (running_mean != nullptr && running_var != nullptr) {
        float old_mean = (float)running_mean[c];
        float old_var  = (float)running_var[c];
        float unbiased_var = (count > 1) ? v * (float)count / (float)(count - 1) : v;
        running_mean[c] = static_cast<T>((1.0f - momentum) * old_mean + momentum * m);
        running_var[c]  = static_cast<T>((1.0f - momentum) * old_var  + momentum * unbiased_var);
      }
    }
    __syncthreads();
    mean    = s_mean;
    inv_std = s_inv_std;
  } else {
    mean    = (float)running_mean[c];
    float v = (float)running_var[c];
    inv_std = rsqrtf(v + eps);
  }

  float gamma = (weight != nullptr) ? (float)weight[c] : 1.0f;
  float beta  = (bias   != nullptr) ? (float)bias[c]   : 0.0f;

  for (int64_t idx = tid; idx < count; idx += nthreads) {
    int n   = (int)(idx / HW);
    int rem = (int)(idx % HW);
    int h   = rem / W;
    int w   = rem % W;
    float v = (float)mX(n, h, w);
    float norm = (v - mean) * inv_std;
    mY(n, h, w) = static_cast<T>(norm * gamma + beta);
  }
}

torch::Tensor batchnorm2d_forward(torch::Tensor x,
                                   torch::Tensor weight,
                                   torch::Tensor bias,
                                   torch::Tensor running_mean,
                                   torch::Tensor running_var,
                                   bool training,
                                   double momentum,
                                   double eps) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(weight.is_cuda() && bias.is_cuda(), "weight/bias must be CUDA");
  TORCH_CHECK(running_mean.is_cuda() && running_var.is_cuda(), "running stats must be CUDA");

  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();
  auto b_c = bias.contiguous();
  auto rm_c = running_mean.contiguous();
  auto rv_c = running_var.contiguous();

  int64_t N = x_c.size(0);
  int64_t C = x_c.size(1);
  int64_t H = x_c.size(2);
  int64_t W = x_c.size(3);

  TORCH_CHECK(w_c.size(0) == C, "weight size mismatch");
  TORCH_CHECK(b_c.size(0) == C, "bias size mismatch");
  TORCH_CHECK(rm_c.size(0) == C, "running_mean size mismatch");
  TORCH_CHECK(rv_c.size(0) == C, "running_var size mismatch");

  auto y = torch::empty_like(x_c);

  const int threads = 256;
  dim3 block(threads);
  dim3 grid((unsigned)C);
  size_t smem_bytes = 2 * threads * sizeof(float);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  batchnorm2d_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      y.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_c.data_ptr<float>(),
      rm_c.data_ptr<float>(),
      rv_c.data_ptr<float>(),
      (int)N, (int)C, (int)H, (int)W,
      (float)eps, (float)momentum, training
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "batchnorm2d_kernel launch failed: ", cudaGetErrorString(err));

  // Copy back updated running stats if they were not the same storage (contiguous() may have copied)
  if (training) {
    if (!running_mean.is_contiguous() || running_mean.data_ptr() != rm_c.data_ptr()) {
      running_mean.copy_(rm_c);
    }
    if (!running_var.is_contiguous() || running_var.data_ptr() != rv_c.data_ptr()) {
      running_var.copy_(rv_c);
    }
  }

  return y;
}
"""

bn_ext = load_inline(
    name="cute_batchnorm2d_ext",
    cpp_sources=bn_cpp_decl,
    cuda_sources=bn_cuda_src,
    functions=["batchnorm2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Batch Normalization implemented with a custom CUDA/CuTe kernel.
    """
    def __init__(self, num_features: int):
        super(ModelNew, self).__init__()
        self.num_features = num_features
        self.weight = nn.Parameter(torch.ones(num_features))
        self.bias = nn.Parameter(torch.zeros(num_features))
        self.register_buffer("running_mean", torch.zeros(num_features))
        self.register_buffer("running_var", torch.ones(num_features))
        self.register_buffer("num_batches_tracked", torch.tensor(0, dtype=torch.long))
        self.momentum = 0.1
        self.eps = 1e-5
        self._ext = bn_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous()
        out = self._ext.batchnorm2d_forward(
            x,
            self.weight,
            self.bias,
            self.running_mean,
            self.running_var,
            self.training,
            float(self.momentum),
            float(self.eps),
        )
        if self.training:
            self.num_batches_tracked += 1
        return out

