_MODULE = None


def _get_module() -> PtxModule:
    global _MODULE
    if _MODULE is None:
        _MODULE = PtxModule(PTX_SOURCE)
    return _MODULE


def validate_generated_code():
    """Compile (lazily) and verify that the expected entry point exists."""
    module = _get_module()
    module.function("bn_forward_kernel")
    return module


class ModelNew(nn.Module):
    """
    Batch Normalization implemented with a hand-authored PTX kernel executed
    through cutegen.ptx_runtime.PtxModule.
    """

    def __init__(self, num_features: int):
        super(ModelNew, self).__init__()
        self.num_features = num_features
        self.weight = nn.Parameter(torch.ones(num_features))
        self.bias = nn.Parameter(torch.zeros(num_features))
        self.register_buffer("running_mean", torch.zeros(num_features))
        self.register_buffer("running_var", torch.ones(num_features))
        self.register_buffer("num_batches_tracked", torch.tensor(0, dtype=torch.long))
        self.momentum = 0.1
        self.eps = 1e-5
        self._module = None

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if self._module is None:
            self._module = _get_module()

        assert x.is_cuda, "x must be CUDA"
        assert x.dim() == 4, "x must be [N, C, H, W]"

        x = x.contiguous()
        if x.dtype != torch.float32:
            x = x.float()

        N, C, H, W = x.shape
        assert C == self.num_features, "channel mismatch"

        weight = self.weight.contiguous()
        bias = self.bias.contiguous()
        running_mean = self.running_mean.contiguous()
        running_var = self.running_var.contiguous()

        y = torch.empty_like(x)

        threads = 256
        grid = (C, 1, 1)
        block = (threads, 1, 1)
        shared_mem_bytes = 2 * threads * 4  # sum + sumsq arrays of float32

        stream = torch.cuda.current_stream().cuda_stream

        self._module.launch(
            "bn_forward_kernel",
            grid=grid,
            block=block,
            shared_mem=shared_mem_bytes,
            stream=stream,
            args=[
                u64(x.data_ptr()),
                u64(y.data_ptr()),
                u64(weight.data_ptr()),
                u64(bias.data_ptr()),
                u64(running_mean.data_ptr()),
                u64(running_var.data_ptr()),
                i32(int(N)),
                i32(int(C)),
                i32(int(H)),
                i32(int(W)),
                f32(float(self.eps)),
                f32(float(self.momentum)),
                i32(1 if self.training else 0),
            ],
        )

        if self.training:
            self.num_batches_tracked += 1

        return y
